    private class Lookup(val ops: List<Cs2Op>) {
        val byId: Map<Int, Cs2Op> = ops.associateBy { it.id }
        val byName: Map<String, Cs2Op> = ops.uniquelyBy { it.opName }
        val byTsName: Map<String, Cs2Op> = ops.uniquelyBy { it.tsName }

        val tagged: Cs2Op? = ops.singleOrNull { it.operand == Cs2Operand.TAGGED }

        /** A name that reached two opcodes would silently stop round-tripping. */
        private fun List<Cs2Op>.uniquelyBy(name: (Cs2Op) -> String): Map<String, Cs2Op> {
            val out = HashMap<String, Cs2Op>(size)
            for (op in this) {
                val previous = out.put(name(op), op)
                require(previous == null) { "Opcodes ${previous!!.id} and ${op.id} share the name ${name(op)}" }
            }
            return out
        }
    }

    private var active = Lookup(revision727)

    val all: List<Cs2Op> get() = active.ops

    /** True while the built-in pre-RS3 table is in use rather than a solved one. */
    val isLegacy: Boolean get() = active.ops === revision727

    /** Replaces the table for the cache in hand; ids and widths differ per build. */
    fun install(ops: List<Cs2Op>) {
        active = Lookup(ops)
    }

    fun restoreLegacy() {
        active = Lookup(revision727)
    }

    operator fun get(id: Int): Cs2Op = active.byId[id] ?: error("Unknown CS2 opcode $id")

    fun find(id: Int): Cs2Op? = active.byId[id]

    fun byName(name: String): Cs2Op? = active.byName[name]

    fun byTsName(name: String): Cs2Op? = active.byTsName[name]

    /**
     * The one opcode whose operand names its own payload, or null on an opcode
     * set that has none. RS3 spells nearly every constant with it.
     */
    fun taggedPush(): Cs2Op? = active.tagged
}
